al_AC = 0xF7;		// debugging constant, odd at all byte boundaries const Byte kDisposedInitVal_AC = 0xD3;		// debugging constant, odd at all byte boundaries #endif//----------------------------------------------------------------------------------------// Global function declarations//----------------------------------------------------------------------------------------inline bool odd_AC(void* value){ return (reinterpret_cast<long>(value) & 0x00000001); }EXPORT_AC Handle DisposeIfHandle_AC(Handle aHandle);EXPORT_AC Ptr DisposeIfPtr_AC(Ptr aPtr);EXPORT_AC Handle NewPermHandle_AC(Size size);// Creates a handle by calling NewHandle, or if a PermHandleHandler is installed, calls thatEXPORT_AC void SetPermHandleSize_AC(Handle h, Size newSize);class EXPORT_AC CPermHandleHandler_AC{public:	CPermHandleHandler_AC();	virtual ~CPermHandleHandler_AC();		virtual Handle DoNewHandle(Size size);		// A subclass may perform pre or post-processing by overriding this & calling inherited.			virtual void DoSetHandleSize(Handle h, Size newSize);		// A subclass may perform pre or post-processing by overriding this & calling inherited.	};EXPORT_AC void SetPermHandleHandler_AC(CPermHandleHandler_AC* newHandler);// Installs a handle allocator which will be used by NewPermHandle and SetPermHandleSize#if TARGET_RT_MAC_CFM#define DisposeIfRoutineDescriptor_AC(p) ((p) ? (DisposeRoutineDescriptor(p), (UniversalProcPtr)NULL) : (UniversalProcPtr)NULL)#else#define DisposeIfRoutineDescriptor_AC(p) (void)NULL#endif//----------------------------------------------------------------------------------------// Handle helpers//----------------------------------------------------------------------------------------template <class T>inline void Lock_AC(T inHandle)// Lock_AC locks the given handle. 	{ ::HLock(reinterpret_cast<Handle>(inHandle)); }template <class T>inline void Unlock_AC(T inHandle)// Unlock_AC unlocks the given handle. 	{ ::HUnlock(reinterpret_cast<Handle>(inHandle)); }template <class T>inline T DisposeIfNotNULL_AC(T& inHandle)	{ return reinterpret_cast<T>(DisposeIfHandle_AC(reinterpret_cast<Handle>(inHandle))); }//----------------------------------------------------------------------------------------// Memory Utilities//----------------------------------------------------------------------------------------EXPORT_AC bool IsAResource_AC(const Handle h);EXPORT_AC bool IsHandle_AC(const Handle h);	// Quick test if a handle is valid. A NULL handle is not valid. 	// Does not test if the handle has been purged. #if qCarbon || qMSWindowsinline bool VerboseIsHandle_AC(const Handle /* h */) { return true; }#elif qCoreDebugEXPORT_AC bool VerboseIsHandle_AC(const Handle h);#elseinline bool VerboseIsHandle_AC(const Handle h) { return IsHandle_AC(h); }#endif	// Test if a handle is valid and report any problems. A NULL handle is not valid. EXPORT_AC bool IsHandleLocked_AC(const Handle h);#if qCoreDebugEXPORT_AC bool IsHandlePurged_AC(const Handle h);#elseinline bool IsHandlePurged_AC(const Handle h) { return (!*h); }#endifEXPORT_AC Size GetHandleSizeIfLocked_AC(const Handle h, bool justLocked);	// Get the size of a handle if it is locked. EXPORT_AC OSErr CopyHandle_AC(const Handle inHandle, Handle& outHandle);	// A nice HandToHand replacement that makes the temp for you.//----------------------------------------------------------------------------------------// Lock a handle, optionally moving it in memory//----------------------------------------------------------------------------------------EXPORT_AC SignedByte LockHandle_AC(Handle h, EMoveHiState_AC high = eDontMoveHi);inline SignedByte LockHandleHigh_AC(Handle h) { return LockHandle_AC(h, eMoveHi); }//----------------------------------------------------------------------------------------// Store a handle's state temporarily, optionally locking it//----------------------------------------------------------------------------------------class EXPORT_AC CTempHLock_AC{public:	CTempHLock_AC(Handle itsData = NULL);	// Sets the pointee to itsData	// and locks the handle.	CTempHLock_AC(Handle itsData, EMoveHiState_AC high, EReleaseState_AC releaseIt = eDontReleaseIt, ELockState_AC lockIt = eLockIt);	// Sets the pointee to itsData	// lockit locks the handle, high moves it high first, releaseit releases (as resource) when done.	~CTempHLock_AC() { RestoreState(); }	// restores the old state	void RestoreState();	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------protected:	Handle	pointee;		// A protected field that contains the temporary handle.	short	fHandleBits;	// A protected field that contains the handle state prior to							// its being locked so that the state can be restored when when							// this object is destroyed.	bool	fRelease;		// A protected field that is true when the handle refers to a							// resource that should released when this object is destroyed.};//----------------------------------------------------------------------------------------// Store a handle's state temporarily, optionally locking it//----------------------------------------------------------------------------------------#define DontUnlock releasetemplate <class T>class TemplateTempHandleLock : public CTempHLock_AC{public:	TemplateTempHandleLock(T inData = NULL) :	CTempHLock_AC(reinterpret_cast<Handle>(inData))	{ }	// Sets the pointee to itsData	// and locks the handle.	TemplateTempHandleLock(T inData, EMoveHiState_AC high, EReleaseState_AC releaseIt = eDontReleaseIt, ELockState_AC lockIt = eLockIt) :	CTempHLock_AC(reinterpret_cast<Handle>(inData), high, releaseIt, lockIt)	{ }	// Sets the pointee to itsData	// lockit locks the handle, high moves it high first, releaseit releases (as resource) when done.	T get() const { return reinterpret_cast<T>(pointee); }	T release() { T oldPointee = get(); pointee = NULL; return oldPointee; }	void reset(T p = NULL) { if (reinterpret_cast<T>(pointee) != p) { RestoreState(); pointee = reinterpret_cast<Handle>(p); } }	TemplateTempHandleLock& operator=(T rhs) { pointee = reinterpret_cast<Handle>(rhs); return *this; }	operator T() { return *reinterpret_cast<T*>(&pointee); }		// Conversion operator, for converting data to desired return type.};typedef TemplateTempHandleLock<Handle> CTempHandleLock_AC;//----------------------------------------------------------------------------------------// Manage a temporary Handle//----------------------------------------------------------------------------------------template <class REF>class CHandleDeleter_AC{public:	static void DeleteRef(REF handle)	{ ::DisposeIfHandle_AC(reinterpret_cast<Handle>(handle)); }};template <class T>class TemplateTempHandle : public CAutoRef_AC< T, CHandleDeleter_AC<T> >{public:	TemplateTempHandle(T inData = NULL) : CAutoRef_AC< T, CHandleDeleter_AC<T> >(inData) { }};typedef TemplateTempHandle<Handle> CTempHandle_AC;//----------------------------------------------------------------------------------------// Manage a temporary Ptr (from the toolbox)//----------------------------------------------------------------------------------------template <class REF>class CMacPtrDeleter_AC{public:	static void DeleteRef(REF ptr)	{ ::DisposeIfPtr_AC(reinterpret_cast<Ptr>(ptr)); }};template <class T>class TemplateTempPtr : public CAutoRef_AC< T, CMacPtrDeleter_AC<T> >{public:	TemplateTempPtr(T inData = NULL) : CAutoRef_AC< T, CMacPtrDeleter_AC<T> >(inData) { }};typedef TemplateTempPtr<Ptr> CTempPtr_AC;//----------------------------------------------------------------------------------------// Manage a temporary RoutineDescriptor//----------------------------------------------------------------------------------------template <class REF>class CRtnDescrptrDeleter_AC{public:	static void DeleteRef(REF desc)	{ #if defined(__SC__) 		(void)desc; // to prevent Warning 35: Parameter 'desc' is not used within function#endif		(void)DisposeIfRoutineDescriptor_AC(static_cast<UniversalProcPtr>(desc)); 	}};template <class T>class TmplTmpRtnDescrptr : public CAutoRef_AC< T, CRtnDescrptrDeleter_AC<T> >{public:	TmplTmpRtnDescrptr(T inData = NULL) : CAutoRef_AC< T, CRtnDescrptrDeleter_AC<T> >(inData) { }};typedef TmplTmpRtnDescrptr<UniversalProcPtr> CTempRoutineDescriptor_AC;#if 1 // ••• change to qBackwardCompatible#define TemplateTempRoutineDescriptor TmplTmpRtnDescrptr#endif/*	Historical Change Record:		----- R13 -----		07/09/97	Added PermHandleHandler so ACS can use MacApp's Perm calls.		06/12/97	Dispose if Handle forgot to return a value.		06/05/97	EXPORT_AC, EXPORT_MA, no-load fixes, Memory_AC, Windows_AC, no CW11orLATER, removed segmentation, etc... 		04/28/97	Static_cast changed to reinterpret_cast and added a missed ')'.		04/28/97	Bug Fixes. Update compile flags to kBlah_AC.		04/25/97	Fixed typo in DisposeIfNotNULL_AC		04/14/97	Update for real xxx_cast operators.		03/25/97	AC_ to _AC Name change.		03/20/97	Moved to Core suite.		03/05/97	Commented out operator -> for 3 handle classes.  Needs to be revisited.		02/07/97	Updated includes.		12/18/96	Split from UCoreUtilities.*/#endif // __CHandle_AC__